/* AI Daily News — client. Loads news.json (regenerated by CI every 3 hours),
   renders group tabs with subcategory dropdowns, a customizable For You feed,
   and an authoritative / public-opinion source filter. */

const REFRESH_INTERVAL_MS = 15 * 60 * 1000;
const FOR_YOU_KEY = "forYouCategories";
const SOURCES_KEY = "sourceTypes";
const DENSITY_KEY = "cardDensity";
const BRIEFING_ON_KEY = "briefingEnabled";
const NOTIFY_ON_KEY = "notifyEnabled";
const BRIEFING_DAY_KEY = "briefingShownDay";
const NOTIFY_DAY_KEY = "notifiedDay";
const FOR_YOU_COUNT = 8;
const BRIEFING_COUNT = 12;
const PER_SECTION = 5;
const DENSITIES = [
  { id: "compact", name: "Compact" },
  { id: "cozy", name: "Cozy" },
  { id: "spacious", name: "Spacious" },
];

const state = { data: null, tab: "all", sub: "all" };

const $feed = document.getElementById("feed");
const $tabs = document.getElementById("tabs");
const $updated = document.getElementById("updated");
const $refresh = document.getElementById("refresh");
const $dialog = document.getElementById("customize-dialog");
const $options = document.getElementById("customize-options");
const $sources = document.getElementById("source-options");
const $density = document.getElementById("density-options");
const $optBriefing = document.getElementById("opt-briefing");
const $optNotify = document.getElementById("opt-notify");
const $briefing = document.getElementById("briefing");

/* ---------- preferences ---------- */

function readPref(key) {
  try {
    const raw = localStorage.getItem(key);
    return raw ? JSON.parse(raw) : null;
  } catch {
    return null;
  }
}

function writePref(key, value) {
  try {
    localStorage.setItem(key, JSON.stringify(value));
  } catch {
    /* private browsing — prefs just won't persist */
  }
}

function allSubs() {
  return state.data.groups.flatMap((g) => g.subs.map((s) => ({ ...s, groupName: g.name })));
}

// null = never customized; [] = customized but nothing picked.
// Ids from older versions that no longer exist are dropped.
function getForYouPrefs() {
  const prefs = readPref(FOR_YOU_KEY);
  if (prefs === null) return null;
  const valid = new Set(allSubs().map((s) => s.id));
  return prefs.filter((id) => valid.has(id));
}

function getSourcePrefs() {
  const prefs = readPref(SOURCES_KEY);
  return Array.isArray(prefs) && prefs.length ? prefs : ["authoritative", "public"];
}

function bySources(articles) {
  const wanted = getSourcePrefs();
  return articles.filter((a) => wanted.includes(a.sourceType ?? "authoritative"));
}

function getDensity() {
  const d = readPref(DENSITY_KEY);
  return DENSITIES.some((x) => x.id === d) ? d : "cozy";
}

function applyDensity() {
  document.body.dataset.density = getDensity();
}

const briefingEnabled = () => readPref(BRIEFING_ON_KEY) !== false; // default on
const notifyEnabled = () => readPref(NOTIFY_ON_KEY) === true; // default off
const todayStamp = () => new Date().toISOString().slice(0, 10);

/* ---------- rendering ---------- */

function relTime(iso) {
  if (!iso) return "";
  const mins = Math.round((Date.now() - new Date(iso).getTime()) / 60000);
  if (mins < 1) return "just now";
  if (mins < 60) return `${mins}m ago`;
  const hours = Math.round(mins / 60);
  if (hours < 24) return `${hours}h ago`;
  return `${Math.round(hours / 24)}d ago`;
}

function renderTabs() {
  const tabs = [{ id: "all", name: "All" }, ...state.data.groups];
  $tabs.replaceChildren(
    ...tabs.map((t) => {
      const b = document.createElement("button");
      b.className = "tab";
      b.role = "tab";
      b.textContent = t.name;
      b.setAttribute("aria-selected", String(state.tab === t.id));
      b.addEventListener("click", () => {
        state.tab = t.id;
        state.sub = "all";
        renderTabs();
        renderFeed();
      });
      return b;
    })
  );
}

function articleCard(a, { badge } = {}) {
  const li = document.createElement("li");
  li.className = "card";
  const link = document.createElement("a");
  link.href = a.url;
  link.target = "_blank";
  link.rel = "noopener";
  const h = document.createElement("p");
  h.className = "headline";
  h.textContent = a.title;
  const by = document.createElement("p");
  by.className = "byline";
  if (badge) {
    const c = document.createElement("span");
    c.className = "cat-badge";
    c.textContent = badge;
    by.append(c);
  }
  if (a.source) {
    const s = document.createElement("span");
    s.className = "source";
    s.textContent = a.source;
    by.append(s);
  }
  const t = document.createElement("span");
  t.textContent = relTime(a.published);
  by.append(t);
  if (a.sourceType === "public") {
    const p = document.createElement("span");
    p.className = "type-badge";
    p.textContent = "💬 opinion";
    by.append(p);
  }
  link.append(h, by);
  li.append(link);
  return li;
}

function mergeNewest(subs, count) {
  const seen = new Set();
  return subs
    .flatMap((s) => bySources(s.articles).map((a) => ({ ...a, subName: s.name })))
    .sort((a, b) => (b.published ?? "").localeCompare(a.published ?? ""))
    .filter((a) => {
      const key = a.title.toLowerCase();
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    })
    .slice(0, count);
}

function sectionTitle(text) {
  const h2 = document.createElement("h2");
  h2.className = "section-title";
  h2.textContent = text;
  return h2;
}

function cardList(articles, opts) {
  const ul = document.createElement("ul");
  ul.className = "card-list";
  ul.append(...articles.map((a) => articleCard(a, opts)));
  return ul;
}

function emptyNote(text) {
  const p = document.createElement("p");
  p.className = "foryou-empty";
  p.textContent = text;
  return p;
}

/* ---------- For You ---------- */

function forYouArticles(prefs) {
  // Round-robin across the chosen subcategories (newest first within each)
  // so one very active feed can't crowd the others out of For You.
  const queues = allSubs()
    .filter((s) => prefs.includes(s.id))
    .map((s) => bySources(s.articles).map((a) => ({ ...a, subName: s.name })));
  const seen = new Set();
  const mixed = [];
  for (let i = 0; mixed.length < FOR_YOU_COUNT; i++) {
    const round = queues.map((q) => q[i]).filter(Boolean);
    if (!round.length) break;
    round.sort((a, b) => (b.published ?? "").localeCompare(a.published ?? ""));
    for (const a of round) {
      const key = a.title.toLowerCase();
      if (seen.has(key)) continue;
      seen.add(key);
      mixed.push(a);
    }
  }
  return mixed.slice(0, FOR_YOU_COUNT);
}

function renderForYou(frag) {
  const prefs = getForYouPrefs();

  const head = document.createElement("div");
  head.className = "foryou-head";
  const h2 = document.createElement("h2");
  h2.className = "section-title foryou-title";
  h2.textContent = "★ For You";
  const btn = document.createElement("button");
  btn.className = "customize-btn";
  btn.textContent = prefs === null ? "Choose topics" : "Customize";
  btn.addEventListener("click", openCustomize);
  head.append(h2, btn);
  frag.append(head);

  if (prefs === null || prefs.length === 0) {
    frag.append(
      emptyNote(
        prefs === null
          ? "Pick the topics you care about and your personal feed will appear here."
          : "No topics selected — tap Customize to pick some."
      )
    );
    return;
  }

  const articles = forYouArticles(prefs);
  if (!articles.length) {
    frag.append(emptyNote("No stories match your topic and source choices right now."));
    return;
  }
  const ul = document.createElement("ul");
  ul.className = "card-list";
  ul.append(...articles.map((a) => articleCard(a, { badge: a.subName })));
  frag.append(ul);
}

/* ---------- customize dialog ---------- */

function sourceCheckbox(id, label, hint, checked) {
  const wrap = document.createElement("label");
  wrap.className = "option";
  const box = document.createElement("input");
  box.type = "checkbox";
  box.value = id;
  box.checked = checked;
  const text = document.createElement("span");
  text.innerHTML = "";
  const strong = document.createElement("strong");
  strong.textContent = label;
  const small = document.createElement("small");
  small.textContent = " — " + hint;
  text.append(strong, small);
  wrap.append(box, text);
  return wrap;
}

function openCustomize() {
  const prefs = getForYouPrefs() ?? [];
  const sources = getSourcePrefs();

  const density = getDensity();
  $density.replaceChildren(
    ...DENSITIES.map((d) => {
      const label = document.createElement("label");
      label.className = "option density-option";
      const radio = document.createElement("input");
      radio.type = "radio";
      radio.name = "density";
      radio.value = d.id;
      radio.checked = d.id === density;
      const span = document.createElement("span");
      span.textContent = d.name;
      label.append(radio, span);
      return label;
    })
  );

  $optBriefing.checked = briefingEnabled();
  $optNotify.checked = notifyEnabled() && ("Notification" in window) && Notification.permission === "granted";

  $sources.replaceChildren(
    sourceCheckbox("authoritative", "Authoritative", "major news outlets", sources.includes("authoritative")),
    sourceCheckbox("public", "Public opinion", "Reddit community posts", sources.includes("public"))
  );

  $options.replaceChildren(
    ...state.data.groups.map((g) => {
      const details = document.createElement("details");
      details.className = "group";
      const summary = document.createElement("summary");
      const groupBox = document.createElement("input");
      groupBox.type = "checkbox";
      groupBox.className = "group-box";
      // clicking the checkbox shouldn't also expand/collapse
      groupBox.addEventListener("click", (e) => e.stopPropagation());
      const name = document.createElement("span");
      name.textContent = g.name;
      const count = document.createElement("span");
      count.className = "group-count";
      summary.append(groupBox, name, count);
      details.append(summary);

      const subBoxes = g.subs.map((s) => {
        const label = document.createElement("label");
        label.className = "option sub-option";
        const box = document.createElement("input");
        box.type = "checkbox";
        box.value = s.id;
        box.checked = prefs.includes(s.id);
        const span = document.createElement("span");
        span.textContent = s.name;
        label.append(box, span);
        details.append(label);
        return box;
      });

      const syncGroupBox = () => {
        const on = subBoxes.filter((b) => b.checked).length;
        groupBox.checked = on === subBoxes.length;
        groupBox.indeterminate = on > 0 && on < subBoxes.length;
        count.textContent = on ? `${on}/${subBoxes.length}` : "";
      };
      groupBox.addEventListener("change", () => {
        subBoxes.forEach((b) => (b.checked = groupBox.checked));
        syncGroupBox();
      });
      subBoxes.forEach((b) => b.addEventListener("change", syncGroupBox));
      syncGroupBox();
      if (subBoxes.some((b) => b.checked)) details.open = true;
      return details;
    })
  );
  $dialog.showModal();
}

// Ask for notification permission the moment the toggle is switched on, so
// the browser prompt appears in response to a user gesture.
$optNotify.addEventListener("change", async () => {
  if (!$optNotify.checked) return;
  if (!("Notification" in window)) {
    $optNotify.checked = false;
    return;
  }
  if (Notification.permission !== "granted") {
    const perm = await Notification.requestPermission();
    if (perm !== "granted") $optNotify.checked = false;
  }
});

$dialog.addEventListener("close", () => {
  if ($dialog.returnValue !== "save") return;
  const picked = [...$options.querySelectorAll("input[value]:checked")].map((b) => b.value);
  writePref(FOR_YOU_KEY, picked);
  const sources = [...$sources.querySelectorAll("input:checked")].map((b) => b.value);
  writePref(SOURCES_KEY, sources.length ? sources : ["authoritative", "public"]);
  const density = $density.querySelector("input:checked");
  if (density) writePref(DENSITY_KEY, density.value);
  writePref(BRIEFING_ON_KEY, $optBriefing.checked);
  writePref(NOTIFY_ON_KEY, $optNotify.checked);
  applyDensity();
  renderFeed();
  maybeNotify();
});

/* ---------- main feed ---------- */

function renderSubPicker(group, frag) {
  const row = document.createElement("div");
  row.className = "sub-picker";
  const label = document.createElement("label");
  label.textContent = "Topic:";
  label.htmlFor = "sub-select";
  const select = document.createElement("select");
  select.id = "sub-select";
  const optAll = document.createElement("option");
  optAll.value = "all";
  optAll.textContent = `All ${group.name}`;
  select.append(
    optAll,
    ...group.subs.map((s) => {
      const o = document.createElement("option");
      o.value = s.id;
      o.textContent = s.name;
      return o;
    })
  );
  select.value = state.sub;
  select.addEventListener("change", () => {
    state.sub = select.value;
    renderFeed();
  });
  row.append(label, select);
  frag.append(row);
}

function renderFeed() {
  const frag = document.createDocumentFragment();

  if (state.tab === "all") {
    renderForYou(frag);
    for (const g of state.data.groups) {
      const articles = mergeNewest(g.subs, PER_SECTION);
      if (!articles.length) continue;
      frag.append(sectionTitle(g.name), cardList(articles));
    }
  } else {
    const group = state.data.groups.find((g) => g.id === state.tab);
    if (group) {
      renderSubPicker(group, frag);
      const shown = state.sub === "all" ? group.subs : group.subs.filter((s) => s.id === state.sub);
      let any = false;
      for (const s of shown) {
        const articles = bySources(s.articles);
        if (!articles.length) continue;
        any = true;
        if (state.sub === "all") frag.append(sectionTitle(s.name));
        frag.append(cardList(state.sub === "all" ? articles.slice(0, PER_SECTION) : articles));
      }
      if (!any) frag.append(emptyNote("No stories match your source filter here right now."));
    }
  }

  $feed.replaceChildren(frag);
  $updated.textContent = `Updated ${relTime(state.data.updated)}`;
}

/* ---------- daily briefing ---------- */

function briefingArticles() {
  const prefs = getForYouPrefs();
  return prefs && prefs.length ? briefingMix(prefs) : mergeNewest(allSubs(), BRIEFING_COUNT);
}

function briefingMix(prefs) {
  // Same round-robin as For You but with the larger briefing count.
  const queues = allSubs()
    .filter((s) => prefs.includes(s.id))
    .map((s) => bySources(s.articles).map((a) => ({ ...a, subName: s.name })));
  const seen = new Set();
  const mixed = [];
  for (let i = 0; mixed.length < BRIEFING_COUNT; i++) {
    const round = queues.map((q) => q[i]).filter(Boolean);
    if (!round.length) break;
    round.sort((a, b) => (b.published ?? "").localeCompare(a.published ?? ""));
    for (const a of round) {
      const key = a.title.toLowerCase();
      if (!seen.has(key)) {
        seen.add(key);
        mixed.push(a);
      }
    }
  }
  return mixed.slice(0, BRIEFING_COUNT);
}

function showBriefing() {
  const prefs = getForYouPrefs();
  const articles = briefingArticles();
  document.getElementById("briefing-date").textContent = new Date().toLocaleDateString(undefined, {
    weekday: "long",
    month: "long",
    day: "numeric",
  });
  document.getElementById("briefing-sub").textContent =
    prefs && prefs.length
      ? "The latest from your topics."
      : "Top stories right now — pick topics in Customize to personalize this.";
  const body = document.getElementById("briefing-body");
  const ul = document.createElement("ul");
  ul.className = "card-list";
  ul.append(...articles.map((a) => articleCard(a, { badge: a.subName })));
  body.replaceChildren(
    articles.length ? ul : emptyNote("Nothing to show yet — check your topic and source settings.")
  );
  $briefing.hidden = false;
  document.body.classList.add("no-scroll");
  document.getElementById("briefing-close").focus();
}

function hideBriefing() {
  $briefing.hidden = true;
  document.body.classList.remove("no-scroll");
}

document.getElementById("briefing-close").addEventListener("click", hideBriefing);
document.getElementById("briefing-open").addEventListener("click", () => {
  if (state.data) showBriefing();
});
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && !$briefing.hidden) hideBriefing();
});

function maybeAutoBriefing() {
  if (!briefingEnabled()) return;
  if (readPref(BRIEFING_DAY_KEY) === todayStamp()) return;
  writePref(BRIEFING_DAY_KEY, todayStamp());
  showBriefing();
}

/* ---------- daily headline notification ---------- */

function topHeadline() {
  const prefs = getForYouPrefs();
  const list = prefs && prefs.length ? briefingMix(prefs) : mergeNewest(allSubs(), 1);
  return list[0] ?? null;
}

function maybeNotify() {
  if (!state.data || !notifyEnabled()) return;
  if (!("Notification" in window) || Notification.permission !== "granted") return;
  if (readPref(NOTIFY_DAY_KEY) === todayStamp()) return;
  const top = topHeadline();
  if (!top) return;
  writePref(NOTIFY_DAY_KEY, todayStamp());
  const n = new Notification("AI Daily News — today's top story", {
    body: top.title + (top.source ? ` (${top.source})` : ""),
    icon: "icons/icon-192.png",
    tag: "daily-headline",
  });
  n.addEventListener("click", () => {
    window.focus();
    showBriefing();
    n.close();
  });
}

// Fires right at midnight while the app is open (the day stamp changes),
// and otherwise on the first visit of the day.
setInterval(maybeNotify, 30 * 1000);

/* ---------- email digest signup ---------- */

// Subscription requests go by email to the site owner, who adds the address
// to the private recipient list (kept in GitHub secrets, never in this
// public repo). Address is assembled at runtime to avoid scraper harvesting.
const OWNER_EMAIL = ["azxfoo", "gmail.com"].join("@");

document.getElementById("digest-subscribe").addEventListener("click", () => {
  const $email = document.getElementById("digest-email");
  const $status = document.getElementById("digest-status");
  const email = $email.value.trim();
  if (!$email.checkValidity() || !email) {
    $status.textContent = "Please enter a valid email address.";
    return;
  }
  const freq = document.querySelector('input[name="digest-freq"]:checked')?.value ?? "daily";
  const subject = encodeURIComponent("News digest subscription");
  const body = encodeURIComponent(
    `Please subscribe ${email} to the ${freq} AI Daily News digest.`
  );
  window.open(`mailto:${OWNER_EMAIL}?subject=${subject}&body=${body}`, "_self");
  $status.textContent =
    `Almost done — your email app just opened with a ${freq} subscription request. ` +
    "Hit send and you'll be added shortly.";
});

/* ---------- data loading ---------- */

async function load({ spin = false } = {}) {
  if (spin) $refresh.classList.add("spinning");
  try {
    const res = await fetch(`news.json?t=${Date.now()}`, { cache: "no-store" });
    if (!res.ok) throw new Error(`HTTP ${res.status}`);
    const firstLoad = !state.data;
    state.data = await res.json();
    renderTabs();
    renderFeed();
    if (firstLoad) {
      maybeAutoBriefing();
      maybeNotify();
    }
  } catch (err) {
    if (!state.data) {
      document.getElementById("status").textContent =
        "Couldn't load headlines. Check your connection and pull to refresh.";
    }
    console.error("news.json load failed:", err);
  } finally {
    $refresh.classList.remove("spinning");
  }
}

applyDensity();
$refresh.addEventListener("click", () => load({ spin: true }));
document.addEventListener("visibilitychange", () => {
  if (!document.hidden) load();
});
setInterval(load, REFRESH_INTERVAL_MS);
load();

if ("serviceWorker" in navigator) {
  navigator.serviceWorker.register("sw.js");
}
